import { sql } from "drizzle-orm";
import { index, integer, sqliteTable, text, uniqueIndex } from "drizzle-orm/sqlite-core";
import { user } from "./auth-schema";

// Users, sessions, Stripe customers and subscriptions live in the Better Auth
// tables (`auth-schema.ts`, generated by `npm run auth:generate -w @repo/api`).
// These are the app's own tables.

/**
 * A plan maps to one Stripe Product and is fed to the Better Auth Stripe plugin.
 * Stripe prices are immutable, so changing a price creates a new Price and
 * archives the old one; existing subscribers keep the price they bought.
 */
export const plans = sqliteTable("plans", {
  id: text("id").primaryKey(), // slug, e.g. "pro"; the plugin's plan name
  name: text("name").notNull(),
  description: text("description").notNull().default(""),
  features: text("features", { mode: "json" }).$type<string[]>().notNull().default(sql`'[]'`),
  stripeProductId: text("stripe_product_id").notNull().unique(),
  monthlyPriceId: text("monthly_price_id"),
  monthlyAmount: integer("monthly_amount"), // minor units (cents)
  yearlyPriceId: text("yearly_price_id"),
  yearlyAmount: integer("yearly_amount"),
  currency: text("currency").notNull().default("usd"),
  maxDevices: integer("max_devices").notNull().default(2),
  trialDays: integer("trial_days").notNull().default(0),
  active: integer("active", { mode: "boolean" }).notNull().default(true),
  sort: integer("sort").notNull().default(0),
  createdAt: integer("created_at", { mode: "timestamp" })
    .notNull()
    .default(sql`(unixepoch())`),
  updatedAt: integer("updated_at", { mode: "timestamp" })
    .notNull()
    .default(sql`(unixepoch())`),
});

/** Desktop installs signed in to an account. Device IDs are random, never hardware fingerprints. */
export const activations = sqliteTable(
  "activations",
  {
    id: text("id").primaryKey(),
    userId: text("user_id")
      .notNull()
      .references(() => user.id, { onDelete: "cascade" }),
    deviceId: text("device_id").notNull(),
    deviceName: text("device_name").notNull().default(""),
    platform: text("platform").notNull(),
    appVersion: text("app_version").notNull().default(""),
    createdAt: integer("created_at", { mode: "timestamp" })
      .notNull()
      .default(sql`(unixepoch())`),
    lastSeenAt: integer("last_seen_at", { mode: "timestamp" })
      .notNull()
      .default(sql`(unixepoch())`),
  },
  (t) => [uniqueIndex("activations_user_device_idx").on(t.userId, t.deviceId)],
);

/**
 * Website traffic, recorded by the web Worker without cookies or IP addresses.
 * A row is either a person arriving from outside the site (a landing: where
 * they came from, the country, the page) or an AI or search agent reading a
 * page (`agent` set). Feeds the admin's Analytics page.
 */
export const siteVisits = sqliteTable(
  "site_visits",
  {
    id: integer("id").primaryKey({ autoIncrement: true }),
    at: integer("at", { mode: "timestamp_ms" }).notNull(),
    path: text("path").notNull(),
    country: text("country"), // ISO 3166 code from Cloudflare
    // People: "Google", "ChatGPT", "Direct", or the referring host.
    source: text("source"),
    channel: text("channel", { enum: ["search", "ai", "social", "referral", "email", "campaign", "direct"] }),
    referrer: text("referrer"), // the referring host only
    query: text("query"), // search terms, when the referrer or utm_term carries them
    utmSource: text("utm_source"),
    utmMedium: text("utm_medium"),
    utmCampaign: text("utm_campaign"),
    device: text("device", { enum: ["mobile", "tablet", "desktop"] }),
    // Agents, as their user agent names them.
    agent: text("agent"),
    agentKind: text("agent_kind", { enum: ["assistant", "ai-search", "ai-training", "search"] }),
  },
  (t) => [index("site_visits_at_idx").on(t.at)],
);

/** Refunds, disputes and fraud warnings surfaced in the admin for a human to act on. */
export const alerts = sqliteTable(
  "alerts",
  {
    id: text("id").primaryKey(), // Stripe event ID, so webhook retries are idempotent
    kind: text("kind", { enum: ["refund", "dispute", "fraud_warning"] }).notNull(),
    stripeCustomerId: text("stripe_customer_id"),
    stripeSubscriptionId: text("stripe_subscription_id"),
    stripeObjectId: text("stripe_object_id").notNull(),
    amount: integer("amount"),
    currency: text("currency"),
    message: text("message").notNull(),
    createdAt: integer("created_at", { mode: "timestamp" })
      .notNull()
      .default(sql`(unixepoch())`),
    resolvedAt: integer("resolved_at", { mode: "timestamp" }),
  },
  (t) => [index("alerts_resolved_idx").on(t.resolvedAt)],
);

export type Plan = typeof plans.$inferSelect;
export type Activation = typeof activations.$inferSelect;
export type SiteVisit = typeof siteVisits.$inferSelect;
export type NewSiteVisit = typeof siteVisits.$inferInsert;
export type Alert = typeof alerts.$inferSelect;
